insert into public.categories (id, name, description) values
  ('ca000000-0000-0000-0000-000000000001', 'Будівельні роботи', 'Фасад та зовнішні роботи, плитка, ремонт, покраска, монтажні та загальнобудівельні роботи, вентиляція.'),
  ('ca000000-0000-0000-0000-000000000002', 'Електрика', 'Електроживлення, освітлення, автомати, розетки, електромережі, дзвінки з вулиці та все, що стосується електрики.'),
  ('ca000000-0000-0000-0000-000000000003', 'Сантехніка', 'Роботи з водопостачанням, проблеми або поламане сантехнічне обладнання, поламаний кран, протікає вода, протікає кран, протікання та подібні проблеми з водою.'),
  ('ca000000-0000-0000-0000-000000000004', 'Каналізація', 'Не збігає вода, забита раковина, не змиває унітаз, не сходить вода, забита каналізація та подібні проблеми зі стоками.')
